export function mapChatSizeToNumber(value: string): number {
    if (typeof value === 'number') {
        return value;
    }

    switch (value) {
        case 'small':
            return 1;
        case 'medium':
            return 2;
        case 'large':
            return 3;
        default:
            return 2;
    }
}

export function mapChatSizeToString(value: number): string {
    if (typeof value === 'string') {
        return value;
    }

    switch (value) {
        case 1:
            return 'small';
        case 2:
            return 'medium';
        case 3:
            return 'large';
        default:
            return 'medium';
    }
}

function mapColourToString(lookup: Array<{ id: number, name: string, hexColour: string }>, value: number): string {
    const colour = lookup[value];
    return colour ? colour.hexColour : lookup[0].hexColour;
}

function mapColourToNumber(lookup: Array<{ id: number, name: string, hexColour: string }>, hex: string): number {
    const index = lookup.findIndex((colour) => colour.hexColour === hex);
    return index > -1 ? index : 0;
}

export function mapChatColourToNumber(hex: string): number {
    return mapColourToNumber(CHAT_COLOURS, hex);
}

export function mapChatColourToString(value: number): string {
    return mapColourToString(CHAT_COLOURS, value);
}

export function mapDabberColourToNumber(hex: string): number {
    return mapColourToNumber(DABBER_COLOURS, hex);
}

export function mapDabberColourToString(value: number): string {
    return mapColourToString(DABBER_COLOURS, value);
}

export function mapChipColourToNumber(hex: string): number {
    return mapColourToNumber(CHIP_COLOURS, hex);
}

export function mapChipColourToString(value: number): string {
    return mapColourToString(CHIP_COLOURS, value);
}
